"""KTX conversion tests use generated bytes and a deterministic encoder fixture."""
import importlib.util
from pathlib import Path
import struct
import os
import shutil
import subprocess
import sys
import tempfile
import unittest

REPO = Path(__file__).resolve().parents[3]
spec = importlib.util.spec_from_file_location('bc_astc', REPO / 'scripts/transcode_bc_astc.py')
assert spec and spec.loader
tool = importlib.util.module_from_spec(spec)
spec.loader.exec_module(tool)


def ktx(fmt=0x83F3, w=7, h=5, mips=3):
    data = tool.MAGIC + struct.pack('<13I', 0x04030201, 0, 1, 0, fmt, 0x1908, w, h, 0, 0, 1, mips, 4) + b'meta'
    for m in range(mips):
        size = ((max(1, w >> m) + 3) // 4) * ((max(1, h >> m) + 3) // 4) * 16
        data += struct.pack('<I', size) + bytes([m]) * size
    return data


class OfflineASTC(unittest.TestCase):
    @unittest.skipUnless(shutil.which(os.environ.get('ASTCENC', 'astcenc')), 'Arm astcenc required for real encoder integration')
    def test_real_encoder_and_content_cache(self):
        encoder = shutil.which(os.environ.get('ASTCENC', 'astcenc'))
        assert encoder
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            # One BC3 block: white RGB, zero alpha. Verify real encode/decode preserves transparency.
            original = ktx(w=4, h=4, mips=1)[:-16] + bytes(8) + b'\xff\xff' + bytes(6)
            source = root / 'source.ktx'
            source.write_bytes(original)
            for name in ('first', 'cached'):
                subprocess.run([sys.executable, str(REPO / 'scripts/transcode_bc_astc.py'), str(source), str(root / f'{name}.ktx'),
                                '--encoder', encoder, '--cache', str(root / 'cache')], check=True, capture_output=True)
            result = (root / 'first.ktx').read_bytes()
            self.assertEqual(result, (root / 'cached.ktx').read_bytes())
            self.assertEqual(source.read_bytes(), original)
            self.assertEqual(len(list((root / 'cache').glob('*.astc'))), 1)
            astc = next((root / 'cache').glob('*.astc'))
            tga = root / 'decoded.tga'
            subprocess.run([encoder, '-dl', str(astc), str(tga)], check=True, capture_output=True)
            decoded = tga.read_bytes()
            self.assertEqual(decoded[16], 32)
            pos, pixels = 18 + decoded[0], bytearray()
            if decoded[2] == 2:
                pixels.extend(decoded[pos:pos + 64])
            else:
                self.assertEqual(decoded[2], 10)  # astcenc may write RLE TGA
                while len(pixels) < 64:
                    packet = decoded[pos]
                    pos += 1
                    count = (packet & 127) + 1
                    if packet & 128:
                        pixels.extend(decoded[pos:pos + 4] * count)
                        pos += 4
                    else:
                        pixels.extend(decoded[pos:pos + count * 4])
                        pos += count * 4
            self.assertEqual(pixels[3::4], bytes(16))

    def test_metadata_mips_lengths_alpha_profile(self):
        for fmt, (vk, srgb) in tool.FORMATS.items():
            original = ktx(fmt)
            calls = []

            def encode(data, f, s, w, h, calls=calls):
                calls.append((f, s, w, h))
                return b'\x7f' * len(data)

            result = tool.transcode(original, encode)
            self.assertEqual(calls, [(vk, srgb, 7, 5), (vk, srgb, 3, 2), (vk, srgb, 1, 1)])
            self.assertEqual(len(result), len(original))
            self.assertEqual(result[64:68], b'meta')
            self.assertEqual(struct.unpack_from('<I', result, 28)[0], 0x93D0 if srgb else 0x93B0)
            self.assertEqual(original, ktx(fmt))

    def test_fail_closed(self):
        data = ktx()
        for bad in (b'', data[:63], data[:-1], data + b'x', ktx(0x83F1), ktx(w=0), ktx(mips=8)):
            with self.subTest(length=len(bad)), self.assertRaises(ValueError):
                tool.transcode(bad, lambda *args: self.fail('invalid input reached encoder'))
        with self.assertRaises(ValueError):
            tool.transcode(data, lambda *args: b'')

    def test_astc_header_validation(self):
        hdr = b'\x13\xab\xa1\x5c\x04\x04\x01' + (7).to_bytes(3, 'little') + (5).to_bytes(3, 'little') + (1).to_bytes(3, 'little')
        self.assertEqual(tool.astc_payload(hdr + bytes(64), 7, 5), bytes(64))
        for bad in (hdr, hdr + bytes(63), b'bad' + bytes(77)):
            with self.assertRaises(ValueError):
                tool.astc_payload(bad, 7, 5)


if __name__ == '__main__':
    unittest.main()
